def findHamiltonianPath(n, edges):
    # Create a graph adjacency list
    graph = [[] for _ in range(n)]
    for edge in edges:
        graph[edge[0] - 1].append(edge[1] - 1)
        graph[edge[1] - 1].append(edge[0] - 1)

    def dfs(node):
        if node == n - 1:
            return True
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        return False

    for start in range(n):
        if dfs(start):
            return "Yes"
    return "No"

