        for j in range(i, len(sequence)):
            # Check all possible sequences starting at i, step forward by 1
            for k in range(i + 1, len(sequence) + 1):
                sequence_ = sequence[:]
                correct = True
                for l in range(i, k):
                    if sequence_[l] in {'L', 'R'} and sequence_[l] == sequence_[l-1]:
                        correct = False
                        break
                    if correct and l < k:
