def d_sort(s, d, k):
    s_str = list(s)
    for i in range(0, len(s), k):
        d_carry_0th = i % d
        if d_carry_0th == 0:
            continue
        for j in range(d_carry_0th):
            s_str.insert(i+j, s_str.pop(d_carry_0th))
    return ''.join(s_str)

def process_shuffling(s, m, ops):
    for k, d in ops:
        s = d_sort(s, d, k)
    return s

