def minister_game(N, start_a, direction_a, start_b, direction_b):
    d_a = {"left": -1, "right": 1}
    d_b = {"left": 1, "right": -1}
    num_a = start_a
    num_b = start_b
    direction_a = d_a[direction_a]
    direction_b = d_b[direction_b]

    while(True):
        if num_a >= N:
            num_a += direction_a
            direction_a = 1 if direction_a == -1 else -1
        if num_a < 0:
            num_a += N
            direction_a = 1 if direction_a == -1 else -1
        if num_b >= N:
            num_b += direction_b
            direction_b = 1 if direction_b == -1 else -1
        if num_b < 0:
            num_b += N
            direction_b = 1 if direction_b == -1 else -1
        if num_a == num_b:
            if direction_a == 1:
                num_a -= direction_a
            if direction_b == 1:
                num_b -= direction_b
            return num_a, num_b

