import sys

def find_winner(num_peoples, num_abilities, abilities):
    nums, counts, cnt = [0] * (num_abilities + 1), [0] * (num_abilities + 1), 0

    for count, ability in abilities:
        nums[ability] = count

    for ability, count in zip(nums, counts):
