from bisect import bisect, bisect_left

def build_cartesian_tree(arr):
    stack = []
    for element in arr:
        index = bisect_left(arr, element)
        while stack and stack[-1] > element:
            stack.pop()
        if stack:
            if index < len(stack):
                parent_index = bisect_left(stack, element)
            else:
                parent_index = index - 1
            stack.insert(parent_index, element)
        else:
            parent_index = index
            stack.append(element)
        subtree_size = len(stack) - parent_index
        yield subtree_size

def calculate_subtree_sums(arr):
    n = len(arr)
    subtree_sums = []

    for i in range(1, n + 1):
        num_rounds = i
        seq = arr[:num_rounds]
        cart_tree = build_cartesian_tree(seq)
        sum_subtrees = sum([next(cart_tree) for _ in range(n - num_rounds)])
        subtree_sums.append(sum_subtrees)

    for rounds in sorted(range(1, len(subtree_sums) + 1), reverse=True):
        print(subtree_sums[rounds - 1])

# Example usage
