class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.adjacency_matrix = [[0 for _ in range(vertices)] for _ in range(vertices)]

    def add_edge(self, u, v):
        self.adjacency_matrix[u-1][v-1] = 1
        self.adjacency_matrix[v-1][u-1] = 1

    def is_hamiltonian_path(self, v):
        # Create a boolean array to keep track of visited vertices and include a flag for the starting vertex
        visited = [False] * self.vertices
        visited[v-1] = True
        # If there's no cycle to form, there can be no hamiltonian path
        if not self.has_cycle(v, visited):
            return False
        return self.dfs(v, visited)

    def has_cycle(self, v, visited):
        for i in range(self.vertices):
            if i not in visited:
                # If the node is not visited and there is an edge to node i, we can call this recursive call
                if self.adjacency_matrix[v-1][i] == 1:
                    if self.has_cycle(i, visited):
                        return True
        return False

    def dfs(self, v, visited):
        # Mark the vertex as visited
        visited[v] = True
        # Recursively call the DFS for the next vertex
        for i in range(self.vertices):
            if i not in visited:
                if self.adjacency_matrix[v-1][i] == 1:
                    if self.dfs(i, visited):
                        return True
        return False

