from collections import deque

def cyclic_shift(sequence):
    sequence = list(sequence)
    sequence.append(sequence.pop(0))
    return ''.join(sequence)

def bfs(sequence):
    queue = deque([sequence])
    visited = set([sequence])
    min_sequence = sequence
    while queue:
        current_sequence = queue.popleft()
        if len(current_sequence) % 2 == 0:
            left_count = current_sequence.count('(')
            right_count = current_sequence.count(')')
        else:
            left_count = current_sequence.count('(') + 1
            right_count = current_sequence.count(')') - 1

        if right_count > 0:
            new_sequence = cyclic_shift(current_sequence)
            if new_sequence not in visited:
                visited.add(new_sequence)
                if len(new_sequence) % 2 == 0 and left_count >= 0 and right_count <= len(new_sequence) / 2:
                    min_sequence = new_sequence
                queue.append(new_sequence)
    return min_sequence

def sol(sequence):
    return bfs(sequence)

