        sequence.append((i, i, nums.count(i)))
    return sequence

def build_cartesian_tree(sequence):
    if not sequence:
        return (None, 0, [])

    _, root_value, subtree_counts = sequence[0]
    root_vertex = Root(vertex_type='root', value=root_value, children=[])
    root_vertex.subtree_size = subtree_counts

    for _, _, count in sequence:
        if count > 1:
            root_vertex.subtree_size += count - 1

    return root_vertex

class Root:
    def __init__(self, vertex_type, value, children):
        self.vertex_type = vertex_type
        self.value = value
        self.children = children
        self.subtree_size = 0

    def add_child_and_update_tree_size(self, child_value, child):
        self.tree_update_count += 1

    @property
    def constellation_size(self):
        if self.vertex_type == 'leaf':
            return {self.value: 1}
        else:
            result = defaultdict(int)
            for child in self.children:
                result.update(child.constellation_size)
            return result

def update_tree_size(parent_vertex, depth, value):
    for child_value in parent_vertex.children:
        if value == child_value:
            child_vertex = child_value
            break

    if len(parent_vertex.children) != 0:
        parent_vertex.add_child_and_update_tree_size(value, child_value)
        changes_in_tree_size := child_vertex.constellation_size[value]
        if depth % 2 == 0:
            changes_in_tree_size += value * 2 - 1
        else:
            changes_in_tree_size -= value *2 - 1
        child_vertex.tree_update_count += changes_in_tree_size
        return

