import heapq

def is_valid_sequence(N, A):
    sequence = []
    for i in range(N):
        if A[i] == -1:
            continue
        if len(sequence) > 0:
            if sequence[-1] <= i:
                return False
        count = 0
        while len(sequence) > 0 and sequence[-1] <= i:
            sequence.pop()
            count += 1
        if count < (N - i):
            return False
        sequence.append(i)
    return True

def generate_sequence(sequence, N):
    return [sequence[i] for i in range(N) if sequence[i] != -1]

def underflow(A):
    min_seen = float('inf')
    for number in A:
        if number != -1:
            min_seen = min(min_seen, number)
        if number < min_seen:
            return False
    return True

def solve(N, A):
    if not underflow(A):
        return -1
    sorted_A = sorted(set(A))
    min_sequence = list(range(1, N+1))
    heapq.heapify(min_sequence)
    i = 0
    for element in sorted_A:
        while i < N and min_sequence[i] < element:
            heapq.heappop(min_sequence)
            i += 1
        heapq.heappush(min_sequence, element)
    return generate_sequence(min_sequence, N)

T = int(input())
for _ in range(T):
    N = int(input())
    A = list(map(int, input().strip().split()))
    if is_valid_sequence(N, A):
        print(' '.join(map(str, solve(N, A))))
    else:
        print(-1)
