            first_card_id = i1
        else:
            first_card_id = i2

        movements = [(0, 1), (0, -1)]
        card_ids = [first_card_id]

        for _ in range(N - 1):
            next_card_id = None
            exchange = False

            if card1[-1] == card2[-1]:
                i_lower = min(len(card1), len(card2))
                if card_ids[-1] >= len(card1) and card1[i_lower:] == card2[-i_lower:]:
                    card_ids.append(first_card_id)
                else:
                    next_card_id = card_ids[-1] + 1
                    exchange = True
            else:
                for dir_, offset in movements:
                    if i_lower := min(offset, i1 + dir_, i2 + dir_, len(card1) == i_lower):
                        next_card_id = card_ids[-1] + offset
                        exchange = False
                        break

            for _ in range(2):
                if exchange:
                    card1, card2 = card2, card1
                card_ids.append(next_card_id)

        final_cards.append(card_ids[-1])

    return final_cards

