import sys

def min_labeled_brackets(sequence):
    stack = []
    level = 0
    for i, char in enumerate(sequence):
        if char == '(':
            stack.append(level)
            level += 1
        elif char == ')':
            level -= 1
            if level == 0:
                previous_level = stack.pop()
                level = previous_level
            else:
                level += 1
                stack.append(min(level, previous_level))

    output = []
    total_levels = 0
    for i, char in enumerate(sequence[::-1]):
        if char == '(':
            total_levels += 1
            output.insert(0, '(')
        else:
            output.insert(0, ')')

    if total_levels % 2 == 1:
        output.append('|')

    return ''.join(output)

