def find_hamiltonian_path(graph):
    vertices = set(graph.keys())
    def dfs(vertex, path):
        if vertex in graph and graph[vertex] - set(path):
            last_vertex = path[-1]
            if last_vertex == 1: 
                return True
            return any(dfs(graph[last_vertex] - set(path), path + [last_vertex]) for last_vertex in graph[vertex] - set(path))
        if not path:
            return True
        next_vertices = graph[path[-1]]
        return all(dfs(next_vertex, path + [next_vertex]) for next_vertex in next_vertices)

    for vertex in vertices:
        if not dfs(vertex, [vertex]):
            return False
    return True

